const smooth1d = (v, R) => v.map((_, i) => {
  let acc = 0, ws = 0;
  for (let k = -R; k <= R; k++) {
    const w = Math.exp(-(k * k) / (2 * (R / 2) ** 2));
    acc += v[Math.min(v.length - 1, Math.max(0, i + k))] * w; ws += w;
